import{c as o,Q as l,j as e,m as g}from"./chunks/framework.DOi4mjdC.js";const u="/assets/%E6%9C%80%E4%BD%B3%E5%AE%9E%E8%B7%B5%E4%BC%98%E5%8C%96Reduce%E4%BD%BF%E7%94%A8%E7%AB%A0%E8%8A%82.B7-L0Th1.png",c=JSON.parse('{"title":"避免同地址访问","description":"","frontmatter":{},"headers":[{"level":1,"title":"避免同地址访问","slug":"避免同地址访问"}],"relativePath":"guide/算子实践参考/SIMD算子性能优化/内存访问/避免同地址访问.md","filePath":"guide/算子实践参考/SIMD算子性能优化/内存访问/避免同地址访问.md"}'),i={name:"guide/算子实践参考/SIMD算子性能优化/内存访问/避免同地址访问.md"};function s(r,t,p,a,q,d){return l(),e("div",null,[...t[0]||(t[0]=[g('<h1 id="避免同地址访问" tabindex="-1">避免同地址访问 <a class="header-anchor" href="#避免同地址访问" aria-label="Permalink to &quot;避免同地址访问&quot;">​</a></h1><p>【优先级】高</p><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>该性能优化指导适用于如下产品型号：</p><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品</li><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品</li></ul></div><p>【描述】MTE2、MTE3、Scalar等单元访问Global Memory数据时，其地址请求会按照512字节粒度对齐后进行处理。当同时访问Global Memory的数据，且地址处于连续的512字节范围内时，由于数据一致性的原因，多个请求会被串行处理，进而影响数据搬运效率。</p><p>当前算子执行机制保证用户Kernel入参（包括Workspace/Tiling）的地址512字节对齐，因此开发者只需要根据地址的偏移量即可判断两个地址是否会落入连续的512字节范围内。</p><p>如下图所示，AI Core内的各个核对Global Memory的数据同时发出读写请求，尽管addr0~addr5是多个不同的地址，但因为落在连续的512字节范围内，被视为同一个地址请求，此时这几个数据请求会被串行处理，数据访问效率会降低。同地址访问的影响受同时访问的核数影响，同地址访问的核数越多时，串行导致的性能劣化越严重。</p><p><img src="'+u+'" alt=""></p><p>避免同地址访问的方法主要有以下两种：<strong>调整数据访问顺序</strong>和<strong>修改切分策略</strong>。下文介绍配套的样例请参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/04_best_practices/04_memory_access_practices/mata_address_conflict" target="_blank" rel="noreferrer">避免同地址访问样例</a>。</p><p><strong>调整数据访问顺序</strong></p><p>以一个形状为 (8192, 128) 的float类型输入进行Adds计算为例。</p><p>为了体现同地址冲突的影响，上述场景设计中每一行的数据大小为512字节（128个float），每个核每一轮计算处理512 * 8字节的数据，并进行全核同步（实际场景中并不需要），每一轮计算都需要等待所有核完成当前数据块的计算后，再进行下一轮。</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;8.303319380901392%&quot;&gt;&lt;p&gt;实现方案&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;45.28375352866739%&quot;&gt;&lt;p&gt;原始实现&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;46.41292709043123%&quot;&gt;&lt;p&gt;优化实现&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;8.303319380901392%&quot;&gt;&lt;p&gt;实现方法&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;45.28375352866739%&quot;&gt;&lt;p&gt;使用16个核参与计算，按列方向进行切分，每个核总计算数据量为8192 * 8；单核执行循环16次，每次计算的数据量为512 * 8；每个核的循环顺序如下图所示，列方向0~15表示每个核的数据块执行顺序。&lt;/p&gt; &lt;p&gt;&lt;span&gt;由于多个核同时访问同一行数据（512字节），导致同地址冲突的发生。&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;46.41292709043123%&quot;&gt;&lt;p&gt;使用16个核参与计算，按列方向进行切分，每个核总计算数据量为8192 * 8；单核执行循环16次，每次计算的数据量为512 * 8；每个核的循环顺序如下图所示，列方向0~15表示每个核的数据块执行顺序。&lt;/p&gt; &lt;p&gt;由于每个核每一轮处理的地址在不同行，不会同时访问连续的512字节，所以不会导致同地址访问冲突。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;8.303319380901392%&quot;&gt;&lt;p&gt;示意图&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;45.28375352866739%&quot;&gt;&lt;p&gt;&lt;span&gt;&lt;img class=&quot;eddx&quot; src=&quot;../../../figures/矩阵编程逻辑位置示意图-57.png&quot; width=&quot;422.94&quot; height=&quot;376.36672500000003&quot;&gt;&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;46.41292709043123%&quot;&gt;&lt;p&gt;&lt;span&gt;&lt;img class=&quot;eddx&quot; src=&quot;../../../figures/矩阵编程逻辑位置示意图-58.png&quot; width=&quot;422.94&quot; height=&quot;376.36672500000003&quot;&gt;&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;8.303319380901392%&quot;&gt;&lt;p&gt;示例代码&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;45.28375352866739%&quot;&gt;&lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot;&gt;for (int32_t i = 0; i &lt; tiling-&gt;loopOneCore; i++) { AscendC::SyncAll(); CopyIn(i); Compute(); AscendC::SyncAll(); CopyOut(i); }&lt;/pre&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;46.41292709043123%&quot;&gt;&lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot;&gt;for (int32_t i = 0; i &lt; tiling-&gt;loopOneCore; i++) { int32_t newProgress = (i + AscendC::GetBlockIdx()) % tiling-&gt;loopOneCore; AscendC::SyncAll(); CopyIn(newProgress); Compute(); AscendC::SyncAll(); CopyOut(newProgress); }&lt;/pre&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><p><strong>修改切分策略</strong></p><p>仍以一个形状为 (8192, 128) 的float类型输入进行Adds计算为例。</p><p>为了体现同地址冲突的影响，上述场景设计中每一行的数据大小为512字节（128个float），每个核每一轮计算处理512 * 8字节的数据，并进行全核同步（实际场景中并不需要），每一轮计算都需要等待所有核完成当前数据块的计算后，再进行下一轮。</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;6.813978389954251%&quot;&gt;&lt;p&gt;实现方案&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;46.00408838703398%&quot;&gt;&lt;p&gt;原始实现&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;47.18193322301178%&quot;&gt;&lt;p&gt;优化实现&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;6.813978389954251%&quot;&gt;&lt;p&gt;实现方法&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;46.00408838703398%&quot;&gt;&lt;p&gt;使用16个核参与计算，按列方向进行切分，每个核总计算数据量为8192 * 8；单核执行循环16次，每次计算的数据量为512 * 8；每个核的循环顺序如下图所示，列方向0~15表示每个核的数据块执行顺序。&lt;/p&gt; &lt;p&gt;&lt;span&gt;由于多个核同时访问同一行数据（512字节），导致同地址冲突的发生。&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;47.18193322301178%&quot;&gt;&lt;p&gt;使用16个核参与计算，按行方向进行切分，每个核总计算数据量为512 * 128；单核执行循环16次，每次计算的数据量为512 * 8；每个核的循环顺序如下图所示（行方向），均为从块0~块15。&lt;/p&gt; &lt;p&gt;由于每个核每一轮处理的地址在不同行，不会同时访问连续的512字节，所以不会导致同地址访问冲突。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;6.813978389954251%&quot;&gt;&lt;p&gt;示意图&lt;/p&gt; &lt;p&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;46.00408838703398%&quot;&gt;&lt;p&gt;&lt;span&gt;&lt;img class=&quot;eddx&quot; src=&quot;../../../figures/矩阵编程逻辑位置示意图-59.png&quot; width=&quot;422.94&quot; height=&quot;376.36672500000003&quot;&gt;&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;47.18193322301178%&quot;&gt;&lt;p&gt;&lt;span&gt;&lt;img class=&quot;eddx&quot; src=&quot;../../../figures/矩阵编程逻辑位置示意图-60.png&quot; width=&quot;422.94&quot; height=&quot;376.36672500000003&quot;&gt;&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;6.813978389954251%&quot;&gt;&lt;p&gt;示例代码&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;46.00408838703398%&quot;&gt;&lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot;&gt;<strong>aicore</strong> inline void Init(GM_ADDR x, GM_ADDR z, AddsCustomTilingData* tilingPtr) { tiling = tilingPtr; xGm.SetGlobalBuffer((<strong>gm</strong> float *)x + AscendC::GetBlockIdx() * tiling-&gt;tileN); zGm.SetGlobalBuffer((<strong>gm</strong> float <em>)z + AscendC::GetBlockIdx() * tiling-&gt;tileN); // we disable the L2 cache mode to highlight the influence of the gm address conflict<br> xGm.SetL2CacheHint(AscendC::CacheMode::CACHE_MODE_DISABLE); zGm.SetL2CacheHint(AscendC::CacheMode::CACHE_MODE_DISABLE); pipe.InitBuffer(inQueueX, BUFFER_NUM, tiling-&gt;tileM * tiling-&gt;tileN * sizeof(float)); pipe.InitBuffer(outQueueZ, BUFFER_NUM, tiling-&gt;tileM * tiling-&gt;tileN * sizeof(float)); }&lt;/pre&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;47.18193322301178%&quot;&gt;&lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot;&gt;<strong>aicore</strong> inline void Init(GM_ADDR x, GM_ADDR z, AddsCustomTilingData</em> tilingPtr) { tiling = tilingPtr; // change the tile method from column split to row split xGm.SetGlobalBuffer((<strong>gm</strong> float *)x + AscendC::GetBlockIdx() * tiling-&gt;tileM * tiling-&gt;n); zGm.SetGlobalBuffer((<strong>gm</strong> float *)z + AscendC::GetBlockIdx() * tiling-&gt;tileM * tiling-&gt;n); // we disable the L2 cache mode to highlight the influence of the gm address conflict xGm.SetL2CacheHint(AscendC::CacheMode::CACHE_MODE_DISABLE); zGm.SetL2CacheHint(AscendC::CacheMode::CACHE_MODE_DISABLE); pipe.InitBuffer(inQueueX, BUFFER_NUM, tiling-&gt;tileM * tiling-&gt;tileN * sizeof(float)); pipe.InitBuffer(outQueueZ, BUFFER_NUM, tiling-&gt;tileM * tiling-&gt;tileN * sizeof(float)); }&lt;/pre&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>你可以通过执行如下命令行，通过msprof工具获取上述示例的性能数据并进行对比。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>msprof op --launch-count=3 --output=./prof ./execute_adds_op</span></span></code></pre></div><p>重点关注PipeUtilization.csv中的aiv_mte2_time(us)和aiv_mte3_time(us)搬运指令耗时。</p></div>',17)])])}const h=o(i,[["render",s]]);export{c as __pageData,h as default};
